  "upgrade.reviewJoin2": " et notre",
  "upgrade.reviewPeriod": ".",
  "upgrade.upgradeNeverRestartsTrial": "Une mise à niveau ne redémarre jamais votre essai gratuit.",
  "upgrade.trialHistoryNote": "Si vous payez pour Essentiel et que vous passez à Affaires, vous gardez le même compte client et le même historique d’essai. Affaires ne comprend pas un essai supplémentaire de sept jours. Si vous passez à un niveau supérieur pendant que votre essai original est toujours en cours, sa date de fin originale ne se réinitialise pas.",
  "upgrade.providerConfirmNote": "Les changements de forfait exigent la confirmation du fournisseur de facturation. Toute différence de prix, proratisation et date d’entrée en vigueur doit être affichée avant que vous approuviez le changement. Une mise à niveau ne doit pas créer un deuxième abonnement simultané.",
  "upgrade.chargedThroughProviderNote": "Les changements de forfait sont facturés par le fournisseur de facturation. Vous pouvez annuler votre abonnement à partir de cette page en utilisant le bouton Annuler l’abonnement sous votre forfait actuel, ou à partir des Réglages. L’annulation arrête les renouvellements futurs à la fin de votre période payée; elle ne met jamais fin à votre accès d’un coup. Les espaces de travail gratuits existants ne sont pas facturés par la consultation de ces options.",
  "billing.cancel.title": "Annuler l’abonnement",
  "billing.cancel.description": "Se désabonner de {plan}. Annuler arrête les renouvellements futurs à la fin de votre période payée — cela ne met jamais fin à votre accès d’un coup.",
  "billing.cancel.yourPlan": "votre forfait",
  "billing.cancel.doneTitle": "Votre abonnement est annulé.",
  "billing.cancel.doneWithEnd": "Vous gardez l’accès complet jusqu’au {endDate}. Après cette date, vous avez une période de grâce en lecture seule de {graceDays} jours — vous pouvez toujours vous connecter et voir vos produits, mais vous ne pouvez rien ajouter, modifier, supprimer, numériser, importer, exporter ni changer. {gracePart}",
  "billing.cancel.graceEndsOn": "Après la fin de la période de grâce de 15 jours le {date}, votre compte et tous ses renseignements sont supprimés de façon permanente et ne peuvent pas être récupérés.",
  "billing.cancel.doneNoEnd": "Vous gardez l’accès complet jusqu’à la fin de votre période payée. Après cela, une période de grâce en lecture seule de 15 jours s’applique. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "Vous avez annulé dans les 3 jours suivant votre premier débit payé, donc vous pourriez être admissible à un remboursement de ce premier paiement. L’annulation n’émet pas elle-même le remboursement — demandez-le par l’entremise de {contact}.",
  "billing.cancel.refundWindowClosed": "L’annulation n’émet pas à elle seule un remboursement. Les remboursements s’appliquent seulement dans les 3 jours suivant le premier débit payé réussi, sur demande par l’entremise de {contact}.",
  "billing.cancel.notCanceledTitle": "Votre abonnement n’a PAS été annulé.",
  "billing.cancel.contactCode": "Si vous communiquez avec {contact}, mentionnez ce code : {code}",
  "billing.cancel.alreadyCanceledTitle": "Cet abonnement est déjà annulé.",
  "billing.cancel.alreadyCanceledWithEnd": "Il se termine le {date}. Vous gardez l’accès complet jusqu’à ce moment. Après cette date, vous avez une période de grâce en lecture seule de {graceDays} jours pour voir vos produits. {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "Il se termine à la fin de la période payée en cours. Vous gardez l’accès complet jusqu’à ce moment.",
  "billing.cancel.appStoreNote": "Si jamais vous vous abonnez par Google Play ou l’App Store d’Apple, vous devrez peut-être l’annuler dans les réglages d’abonnement de ce magasin. Cette boîte de dialogue ne peut pas arrêter la facturation d’un magasin d’applications. Désinstaller l’application ou supprimer votre compte StockHaven n’annule pas un abonnement d’un magasin.",
  "billing.cancel.trialNote": "Annuler pendant votre essai vous garde vos 7 jours complets — l’accès se termine le {date}, et vous ne serez pas facturé.",
  "billing.cancel.trialNoteNoDate": "Annuler pendant votre essai vous garde vos 7 jours complets, et vous ne serez pas facturé.",
  "billing.cancel.keepAccessUntil": "Vous gardez l’accès complet jusqu’au {date}.",
  "billing.cancel.endOfPaidPeriod": "la fin de votre période payée",
  "billing.cancel.keepAccessRest": "L’annulation arrête seulement les renouvellements futurs — elle ne met jamais fin à votre accès d’un coup, et aucun mois gratuit supplémentaire n’est ajouté.",
  "billing.cancel.gracePeriodTitle": "Après cette date, une période de grâce en lecture seule de {graceDays} jours.",
  "billing.cancel.gracePeriodRest": "Vous pouvez toujours vous connecter et voir vos produits, pour regarder ce que vous aviez et le noter. Tout le reste est bloqué : aucun ajout, modification, suppression, numérisation, importation, exportation ou migration, aucun réglage, aucun personnel.",
