  "exports.eyebrow": "Données",
  "exports.title": "Exportations et sauvegardes",
  "exports.subtitleStart": "Les téléchargements sont toujours limités à",
  "exports.subtitleRest": ". Chaque fichier est étiqueté avec le nom de l’entreprise et la date de sa création.",
  "exports.createBusinessFirst": "Créez d’abord une entreprise — les exportations appartiennent à une entreprise, et non à l’application.",
  "exports.lockedTitle": "Les exportations CSV et Excel sont une fonction d’Affaires",
  "exports.lockedDesc": "Votre espace de travail est sur le forfait Essentiel. Affaires ajoute les exportations CSV et Excel, l’évaluation des stocks, les produits et le personnel illimités, les fournisseurs, les achats et les ensembles.",
  "exports.seeBusiness": "Voir ce qu’Affaires comprend",
  "exports.whatTheseAre": "Ce que ces fichiers sont",
  "exports.about1": "Chaque ensemble de données est offert en CSV ou en vrai classeur Excel (.xlsx) — le cahier d’inventaire complet est Excel seulement, avec une feuille par ensemble de données. Les fichiers CSV s’ouvrent dans Excel, Numbers, Google Sheets et la plupart des applications de stock. Le texte UTF-8, les virgules entre guillemets, les sauts de ligne dans les notes et les zéros initiaux dans les codes sont tous préservés, et les cellules qui commencent comme une formule sont neutralisées pour qu’un chiffrier les ouvre comme du texte.",
  "exports.about2": "Dans les fichiers Excel, les SKU, les UPC, les ISBN et les codes à barres sont des cellules de texte — jamais en notation scientifique et jamais de zéros coupés — avec des largeurs de colonnes, des filtres d’en-tête et des formats de devise ou de quantité appliqués. Le cahier d’inventaire complet garde les produits, les niveaux de stock, les emplacements et les mouvements sur des feuilles distinctes.",
  "exports.about3": "Les très grosses exportations s’arrêtent à 20 000 lignes par ensemble de données — quand cela arrive, le nom du fichier le dit (tronqué-20000), pour qu’un fichier partiel ne passe jamais pour complet.",
  "exports.about4": "Une sauvegarde est un instantané de vos données, et non une restauration en un clic. La restaurer est un travail manuel, avec révision d’abord, donc gardez le fichier en sécurité — rien dans l’application ne peut recréer une entreprise supprimée à partir de celui-ci pour l’instant. Le code de l’application et les sauvegardes de la plateforme Base44 sont gérés séparément de ces fichiers.",
  "exports.about5": "Les photos et les pièces jointes sont énumérées comme leurs liens stockés — les fichiers d’images eux-mêmes ne sont pas emballés dans le téléchargement.",
  "exports.backupTitle": "Sauvegarde complète",
  "exports.backupDesc": "Un fichier avec les produits, les emplacements, les niveaux de stock, le registre complet des mouvements, les fournisseurs, les achats, les commandes, les retours, les comptages et les annonces de cette entreprise — plus ses réglages de profil. Gardez-le à un endroit que vous contrôlez.",
  "exports.backupIncludes1": "Produits, codes, coûts et notes",
  "exports.backupIncludes2": "Emplacements et quantités par emplacement",
  "exports.backupIncludes3": "Chaque mouvement, avec l’auteur et l’heure",
