  "import.createTitle": "Créer de nouveaux produits",
  "import.createDesc": "ajoute des lignes qui ne figurent pas encore au catalogue. Les SKU et les codes à barres en double déjà utilisés sont ignorés, et le stock d’ouverture peut aboutir dans un emplacement choisi comme une réception.",
  "import.updateTitle": "Mettre à jour des produits existants",
  "import.updateDesc": "fait correspondre chaque ligne par SKU ou ID de dossier et montre l’ancienne valeur à côté de la nouvelle proposée. Les cellules vides laissent la valeur enregistrée telle quelle, à moins de demander l’effacement des vides, et les quantités ne sont jamais touchées.",
  "import.receiveModeTitle": "Recevoir du stock",
  "import.receiveModeDesc": "ajoute les quantités qui arrivent à un emplacement et inscrit une réception au registre des mouvements pour chaque ligne. Chaque lot est marqué, pour que la même feuille ne puisse pas être reçue deux fois.",
  "import.excelNote": "Les classeurs Excel (.xlsx) sont lus directement — choisissez la feuille de calcul et les colonnes sont associées pour vous. Les codes restent entiers : un UPC enregistré comme texte garde ses chiffres et ses zéros initiaux. Les lignes qui ne peuvent pas être importées sont énumérées avec un motif",
