  "print.pickOrderHint": "Choisissez un bon de commande dans la liste pour prévisualiser le document.",
  "print.pickCustomerOrderHint": "Choisissez une commande client dans la liste pour prévisualiser le document.",
  "print.pickReturnHint": "Choisissez un retour inscrit dans la liste pour prévisualiser le document.",
  "print.chooseStyleHint": "Choisissez un style, puis choisissez des produits dans la liste. L’aperçu montre exactement ce qui sort de l’imprimante.",
  "print.howToReach": "Comment joindre votre imprimante",
  "print.howIntro": "Cette application se connecte à des imprimantes que vous possédez déjà — elle n’est pas elle-même une imprimante. Il y a quatre façons d’en joindre une, et les étiquettes s’impriment sur les deux forfaits par n’importe laquelle d’elles. Les bordereaux d’emballage, les bons de commande, les documents des fournisseurs et les rapports sont réservés à Affaires, quelle que soit la connexion.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "À partir de cette page, sur Chrome ou Edge sur ordinateur et sur Chrome sur Android : choisissez votre imprimante d’étiquettes et les étiquettes y vont directement. Cela ne fonctionne pas dans Safari sur iOS — sur un iPhone, l’impression Bluetooth vient plutôt avec l’application mobile. Une imprimante qui ne parle que le langage Zebra ZPL ou le langage propre à Brother ne comprendra pas les étiquettes que cette page envoie; cela est vérifié avec de vraies imprimantes avant d’être déclaré fonctionnel.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Installez l’imprimante sur le Wi-Fi de votre boutique, puis utilisez le bouton Imprimer — l’impression passe par l’imprimante installée sur cet ordinateur, par le réseau de la boutique. Sur un iPhone, AirPrint est intégré : une imprimante AirPrint sur le même Wi-Fi apparaît simplement dans la feuille d’impression, sans fil ni application, et l’application n’a besoin d’aucun code propre à AirPrint. L’imprimante doit prendre en charge AirPrint (la plupart des nouvelles le font) et le téléphone et l’imprimante doivent être sur le même Wi-Fi.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Branchez l’imprimante à votre réseau de boutique avec un câble Ethernet, installez-la sur l’ordinateur et imprimez avec le bouton Imprimer. Ethernet est un chemin pour ordinateur de bureau et ordinateur — les iPhone n’utilisent pas de câbles Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Branchez l’imprimante à l’ordinateur avec son câble et utilisez le bouton Imprimer — l’impression passe par l’imprimante qui y est installée. Sur un téléphone Android avec un câble USB OTG, le bouton USB ci-dessus parle directement à l’imprimante. Les iPhone ne peuvent pas imprimer directement par USB — pas de WebUSB là — donc utilisez le Wi-Fi / AirPrint, ou Bluetooth à partir de l’application mobile.",
  "print.howCordsLead": "Les câbles servent encore aux iPhone, à une étape de distance.",
  "print.howCordsBody": "Une imprimante USB branchée à l’ordinateur de la boutique, ou une imprimante Ethernet câblée au réseau, apparaît sur votre iPhone par le Wi-Fi de la boutique (AirPrint / imprimante partagée) — les câbles mettent l’imprimante solidement sur le réseau, et le téléphone la joint sans fil.",
  "print.howOfflineLead": "Si Internet tombe,",
  "print.howOfflineBody": "les étiquettes et les documents déjà sur cette page s’impriment quand même — le bouton Imprimer, les étiquettes PDF, Bluetooth et USB n’ont besoin d’aucune connexion. Ce qui a besoin d’Internet, c’est de charger la page et ses produits au départ. Le mode hors ligne complet (travailler dans l’application sans aucune connexion) est une construction distincte et plus grosse, et il n’est pas revendiqué ici.",
