  "settings.cancelTerms.appleLink": "Instructions d’annulation Apple",
  "settings.cancelTerms.googlePlayLink": "Instructions d’annulation Google Play",
  "settings.cancelTerms.graceTitle": "Après la fin de votre période payée — grâce de 15 jours, puis suppression :",
  "settings.cancelTerms.intro": "Voici les conditions des abonnements payants de Luminous StockHaven. La facturation des abonnements du site Web passe par Stripe. Vous pouvez annuler votre abonnement vous-même à tout moment en utilisant le bouton Annuler l’abonnement ci-dessous — aucune approbation du personnel n’est nécessaire. Les demandes d’annulation et de remboursement peuvent aussi être traitées par le contact officiel du soutien à la clientèle, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Vous pouvez annuler votre abonnement vous-même à tout moment. Aucune approbation du personnel n’est requise. Les renouvellements futurs s’arrêtent seulement après que le fournisseur de facturation a confirmé l’annulation.",
  "settings.cancelTerms.noApprovalTitle": "Annuler sans approbation :",
  "settings.cancelTerms.paymentBody": "Pour les essais payants, l’essai de sept jours exige un mode de paiement à l’inscription. À moins d’annuler dans le délai d’annulation d’essai applicable, le forfait mensuel choisi sera débité automatiquement après l’essai. Le prix, la première date de facturation et le délai d’annulation propre au fournisseur doivent être affichés pendant l’inscription. La facturation de l’essai passe par Stripe.",
  "settings.cancelTerms.paymentTitle": "Mode de paiement et renouvellement automatique :",
  "settings.cancelTerms.remainingBody": "Si vous avez déjà payé une période de facturation, vous pouvez garder l’accès jusqu’à cette date de fin de période payée vérifiée. Une résiliation anticipée exige une confirmation appropriée du fournisseur et tout traitement de remboursement applicable. L’accès à l’essai gratuit se termine selon la date de fin d’essai confirmée par le fournisseur.",
  "settings.cancelTerms.remainingTitle": "Accès restant :",
  "settings.cancelTerms.storesBody": "Si jamais vous vous abonnez par Google Play ou l’App Store d’Apple, votre abonnement est facturé et géré par ce magasin. Vous devrez peut-être l’annuler directement dans la section des abonnements du même compte Google ou Apple utilisé pour vous abonner. Annuler un abonnement distinct du site Web, désinstaller cette application ou demander la suppression du compte Luminous StockHaven n’annule pas automatiquement un abonnement facturé par un magasin. Vérifiez votre reçu d’achat pour confirmer qui vous facture.",
  "settings.cancelTerms.storesTitle": "Abonnements Google Play et App Store d’Apple (si jamais vous vous abonnez par un magasin) :",
  "settings.cancelTerms.title": "Conditions d’annulation",
  "settings.cancelTerms.trialBody": "L’essai de sept jours ne peut être utilisé qu’une fois par client admissible. Annuler un essai ou un abonnement n’accorde pas un autre essai; les clients qui reviennent doivent choisir un abonnement payant.",
  "settings.cancelTerms.trialTitle": "Un seul essai gratuit :",
  "settings.canceled.endsOn": "Cet abonnement est annulé et se termine le {date}. Vous gardez l’accès complet jusqu’à ce moment.",
  "settings.delete.checking": "Vérification d’une demande de suppression existante…",
  "settings.delete.description": "Demander le retrait de votre compte de connexion Luminous StockHaven.",
  "settings.delete.dialogDescription": "Cela demande une révision de la suppression du compte. Cela ne retire pas immédiatement votre connexion ni votre inventaire, et cela n’annule aucun abonnement Stripe. Tapez {word} pour confirmer que vous voulez soumettre la demande.",
  "settings.delete.dialogTitle": "Demander la suppression du compte",
  "settings.delete.enterDelete": "Entrez {word} pour confirmer",
  "settings.delete.exportFirst": "Exportez d’abord votre inventaire si vous devez garder vos dossiers.",
  "settings.delete.intro": "Soumettre une demande ne supprime pas immédiatement votre compte, vos entreprises ou votre inventaire. Les demandes sont révisées séparément avant que la suppression puisse être complétée. Cette demande n’annule pas un abonnement Stripe et n’arrête pas la facturation future; l’annulation de l’abonnement doit être traitée séparément par le fournisseur de facturation.",
  "settings.delete.keepAccount": "Garder le compte",
  "settings.delete.noExport": "Essentiel n’a pas d’exportation — notez tout ce dont vous avez besoin avant de demander la suppression.",
