  "settings.trial.cancelKeeps": "Annuler pendant votre essai vous garde vos 7 jours complets — l’accès se termine le {date}, et vous ne serez pas facturé.",
  "staff.access.noSeatBody": "Votre compte n’a pas de siège de personnel pour cette entreprise, donc son stock reste fermé. Demandez au propriétaire de vous ajouter dans Personnel et rôles.",
  "staff.access.noSeatTitle": "Cette entreprise n’est pas ouverte à votre connexion",
  "staff.access.pendingBody": "Cette entreprise a une invitation pour votre courriel qui n’a pas été activée. Demandez au propriétaire de mettre votre statut de personnel à actif. Rien ici n’est visible avant cela.",
  "staff.access.pendingTitle": "Votre invitation n’est pas encore active",
  "staff.access.signOut": "Se déconnecter",
  "staff.access.suspendedBody": "Un administrateur a suspendu ce compte de personnel pour l’entreprise active. Demandez-lui de vous remettre à actif, puis connectez-vous de nouveau.",
  "staff.access.suspendedTitle": "Votre accès est en pause",
  "staff.addFirst": "Ajouter le premier membre du personnel",
  "staff.addMember": "Ajouter un membre du personnel",
  "staff.emptyBody": "Ajoutez une personne, donnez-lui un rôle et les permissions qui vont avec, et elle est invitée par courriel à se connecter à cette entreprise.",
  "staff.emptyTitle": "Aucun personnel pour l’instant",
  "staff.eyebrow": "Équipe",
  "staff.how.p1": "Chaque membre a un rôle et sa propre liste de permissions, donc vous pouvez partir d’un rôle et changer une chose sans créer un nouveau rôle. Modifier un rôle ne réécrit pas les membres qui y sont déjà — ouvrez un membre pour réappliquer les valeurs par défaut de son rôle.",
  "staff.how.p2": "Les rôles personnalisés sont une fonction d’Affaires : Essentiel utilise les cinq rôles intégrés (propriétaire, gestionnaire, commis au stock, commis aux ventes, observateur).",
  "staff.how.p3": "Les invitations sont envoyées par courriel. Un membre peut seulement se connecter une fois qu’il a accepté, et retirer quelqu’un de cette liste ne supprime pas son compte d’application.",
  "staff.how.p4": "Un magasin est l’emplacement auquel une personne est assignée. Il est inscrit sur sa fiche; ce qu’elle peut ouvrir est toujours décidé par son rôle et ses permissions.",
  "staff.how.p5": "Les permissions décident ce que chaque personne peut ouvrir : les éléments de menu hors de son rôle sont masqués, et une adresse bloquée affiche un avis « pas sur votre rôle » au lieu de la page. Un changement s’applique la prochaine fois que cette personne charge l’application; suspendre un membre le verrouille entièrement.",
  "staff.how.p6": "Les administrateurs peuvent voir et modifier toutes les données, gérer les utilisateurs et les rôles de l’application, et ne sont jamais limités par un rôle de personnel. Une personne sans dossier de personnel — le propriétaire d’une nouvelle entreprise — garde l’accès complet.",
  "staff.howTitle": "Comment le personnel et les rôles fonctionnent",
