  "payroll.dd.help": "Recueillez les coordonnées bancaires de chaque membre de l’équipe en toute sécurité. Les coordonnées envoyées vont au propriétaire seulement — personne d’autre ne peut les voir.",
  "payroll.dd.invite": "Envoyer la demande",
