  "payroll.dd.savings": "Épargne",
  "payroll.dd.steps.body": "1. Il vous faut un compte bancaire d’entreprise qui peut envoyer des paiements ACH. 2. Recueillez un formulaire d’autorisation signé de chaque membre de l’équipe — un chèque annulé aide à vérifier les numéros. 3. Envoyez la paie 2 à 3 jours ouvrables avant le jour de paie pour que l’argent arrive à temps. 4. La plupart des États exigent le consentement écrit du membre de l’équipe. Cette application recueille les formulaires et vous guide étape par étape — l’envoi de l’argent se fait par votre propre banque.",
