  "training.warningSentOn": "Avertissement envoyé le {date}",
  "auth.sameEmailNotice": "Vous avez déjà notre application par Google Play ou l’App Store? Utilisez le même courriel ici — celui avec lequel vous vous connectez à l’application — pour que votre magasin et votre inventaire vous suivent. Un courriel différent commence une toute nouvelle vitrine, vide.",
