  "rewards.status.void": "Annulée",
  "rewards.subtitle": "Dites merci avec une récompense — un pourcentage de rabais, une carte-cadeau, ou n’importe quoi que vous décrivez.",
  "rewards.title": "Récompenses et incitatifs",
  "rewards.value.giftCard": "Carte-cadeau de {value}",
  "rewards.value.percentOff": "Rabais de {percent}% en magasin",
  "rewards.void": "Annuler",
  "rewards.voided": "Récompense annulée.",
  "workforce.tab.rewards": "Récompenses",
  "training.lessons.mgr-give-rewards.step1": "Ouvrez Main-d’œuvre et touchez Récompenses. Choisissez le membre de l’équipe, puis le type : un pourcentage de rabais en magasin, une carte-cadeau, ou autre chose que vous décrivez dans vos propres mots.",
  "training.lessons.mgr-give-rewards.step2": "Donnez un court nom à la récompense et une note si vous voulez. La personne reçoit une cloche tout de suite, et la récompense attend dans ses Mes récompenses avec son propre code.",
  "training.lessons.mgr-give-rewards.step3": "La limite, par conception : vous récompensez le PERSONNEL seulement. Vous ne pouvez pas vous récompenser vous-même ni un autre gestionnaire — récompenser un gestionnaire est la décision du propriétaire, et l’application le refusera franchement.",
  "training.lessons.mgr-give-rewards.step4": "À la caisse, tapez le code que le membre de l’équipe vous montre et marquez-le utilisé — chaque code fonctionne une fois. Vous pouvez annuler une récompense que vous avez donnée si les plans changent; les cadeaux du propriétaire sont au propriétaire à annuler.",
  "training.lessons.mgr-give-rewards.title": "Donner des récompenses à votre personnel",
  "training.lessons.owner-give-rewards.step1": "Les récompenses vivent dans Main-d’œuvre, dans l’onglet Récompenses, et elles sont réservées au forfait Business — avec Essentials, l’onglet montre une porte verrouillée, pour que votre équipe voie ce que le plus gros forfait contient.",
  "training.lessons.owner-give-rewards.step2": "Vous pouvez récompenser N’IMPORTE QUI dans l’équipe — personnel et gestionnaires pareil. Choisissez la personne, puis le type : un pourcentage de rabais en magasin (le pourcentage que vous choisissez), une carte-cadeau pour n’importe où, ou n’importe quel incitatif que vous décrivez dans vos propres mots.",
  "training.lessons.owner-give-rewards.step3": "La récompense arrive avec son propre code à usage unique et fait sonner la cloche de la personne. Elle montre le code à la caisse; un propriétaire ou un gestionnaire le tape pour le marquer utilisé.",
  "training.lessons.owner-give-rewards.step4": "Un bon de récompense imprimé ou partagé porte le nom de VOTRE entreprise seulement — jamais celui de l’application. C’est le merci de votre magasin, pas une publicité.",
  "training.lessons.owner-give-rewards.title": "Donner des récompenses (forfait Business)",
  "training.lessons.owner-rewards-oversight.step1": "Votre gestionnaire peut donner des récompenses aussi — au personnel seulement. L’application refuse qu’un gestionnaire se récompense lui-même ou un autre gestionnaire; récompenser un gestionnaire est toujours votre décision.",
  "training.lessons.owner-rewards-oversight.step2": "Vous voyez chaque récompense dans l’entreprise dans l’Historique des récompenses : qui l’a donnée, qui l’a reçue, et si elle est prête, utilisée ou annulée. Un gestionnaire voit seulement les récompenses qu’il a données et celles qu’il a reçues.",
  "training.lessons.owner-rewards-oversight.step3": "Vous pouvez annuler n’importe quelle récompense, y compris une que votre gestionnaire a donnée. Un gestionnaire peut annuler ses propres cadeaux, mais jamais les vôtres.",
  "training.lessons.owner-rewards-oversight.step4": "Chaque code fonctionne exactement une fois, et une récompense annulée ne peut jamais être utilisée — l’historique montre toujours comment une récompense s’est terminée.",
  "training.lessons.owner-rewards-oversight.title": "Superviser les récompenses : les dons de votre gestionnaire",
  "training.lessons.staff-your-rewards.step1": "Quand votre gestionnaire ou le propriétaire vous donne une récompense, votre cloche sonne. Ouvrez Main-d’œuvre et touchez Récompenses pour la voir sous Mes récompenses.",
  "training.lessons.staff-your-rewards.step2": "Chaque récompense a son propre code. Gardez-le pour vous — celui qui montre le code à la caisse est celui qui utilise la récompense.",
  "training.lessons.staff-your-rewards.step3": "Pour l’utiliser, montrez le code quand vous achetez. La personne à la caisse le tape et le marque utilisé — chaque code fonctionne exactement une fois.",
  "training.lessons.staff-your-rewards.step4": "Les récompenses sont un plaisir du forfait Business. Si votre magasin n’est pas avec Business, l’onglet Récompenses montre une porte verrouillée plutôt — c’est le forfait, pas une erreur.",
  "training.lessons.staff-your-rewards.title": "Vos récompenses : trouver votre code et l’utiliser",
