  "pos.events.heldPlanNote": "Certaines ventes ci-dessous sont arrivées pendant que ce magasin n’était pas avec le forfait Business. Elles ont été gardées en sécurité et rien n’a été compté. Maintenant que le magasin est avec Business, vous pouvez les compter.",
